INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ich bei der Bewertung von Gefahren nur finanzielle Risiken betrachte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch operative und strategische Risiken zählen"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft mir, potenzielle Gefahren systematisch zu identifizieren?', 3, '[{"text": "SWOT-Analyse", "correct": true, "because": "Deckt Schwächen und Bedrohungen auf"}, {"text": "Gantt-Diagramm", "correct": false, "because": "Für Zeitplanung"}, {"text": "ER-Diagramm", "correct": false, "because": "Für Datenmodelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind bei der Bewertung von Risiken entscheidend?', 5, '[{"text": "Eintrittswahrscheinlichkeit", "correct": true, "because": "Misst Häufigkeit"}, {"text": "Schadenspotenzial", "correct": true, "because": "Bewertet Auswirkung"}, {"text": "Projektfarben", "correct": false, "because": "Irrelevant"}, {"text": "Teamgröße", "correct": false, "because": "Kein direkter Risikofaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Risiken werden qualitativ und quantitativ bewertet. b) Sie betreffen nur IT-Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Risiken sind universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer Gefahrenbewertung?', 4, '[{"text": "Stakeholder-Input", "correct": false, "because": "Liefert wichtige Perspektiven"}, {"text": "Risikokategorien", "correct": false, "because": "Strukturieren Analyse"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Risikofaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Gefahrenbewertung einmalig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierliche Überprüfung nötig"}, {"text": "Ja", "correct": false, "because": "Regelmäßige Updates erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft, Ursachen von Gefahren zu analysieren?', 4, '[{"text": "Ishikawa-Diagramm", "correct": true, "because": "Visualisiert Ursachen"}, {"text": "Kanban-Board", "correct": false, "because": "Für Aufgabenmanagement"}, {"text": "Mindmap", "correct": false, "because": "Zu allgemein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Bewertung von Gefahren nur für große Projekte relevant ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte haben Risiken"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Gefahrenbewertung nur für technische Risiken?', 2, '[{"text": "Nein", "correct": true, "because": "Auch menschliche, finanzielle Risiken"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei einer Gefahrenbewertung essenziell?', 5, '[{"text": "Risikoerkennung", "correct": true, "because": "Findet Bedrohungen"}, {"text": "Risikobewertung", "correct": true, "because": "Priorisiert Gefahren"}, {"text": "Teamfeier", "correct": false, "because": "Kein Analysefaktor"}, {"text": "Farbcodierung", "correct": false, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines IT-Projekts priorisieren?', 4, '[{"text": "Sicherheitsrisiken", "correct": true, "because": "Hohe Auswirkungen möglich"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Designaspekte", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FMEA analysiert Fehlerquellen. b) Sie ersetzt Risikomanagement.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt Management"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine effektive Gefahrenbewertung?', 3, '[{"text": "Risikomatrix", "correct": false, "because": "Visualisiert Prioritäten"}, {"text": "Datenquellen", "correct": false, "because": "Liefern Fakten"}, {"text": "Dekorative Diagramme", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Risiken priorisiere?', 4, '[{"text": "Wahrscheinlichkeit und Auswirkung bewerten", "correct": true, "because": "Ermöglicht Priorisierung"}, {"text": "Nur Intuition nutzen", "correct": false, "because": "Unzuverlässig"}, {"text": "Zufällig wählen", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Gefahrenbewertung immer teuer ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kosteneffizient bei Planung"}, {"text": "Ja", "correct": false, "because": "Verhütet größere Schäden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Risiken langfristig zu managen?', 4, '[{"text": "Kontinuierliche Überwachung", "correct": true, "because": "Erkennt Veränderungen"}, {"text": "Einmalige Analyse", "correct": false, "because": "Zu statisch"}, {"text": "Maximale Dokumentation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Gefahrenbewertung nur für Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Betrieb, Strategien"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine strukturierte Gefahrenbewertung?', 5, '[{"text": "Frühzeitige Erkennung", "correct": true, "because": "Verhindert Schäden"}, {"text": "Bessere Entscheidungen", "correct": true, "because": "Basiert auf Daten"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Dokumentation nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Gefahrenbewertung unwichtig?', 3, '[{"text": "Risikoidentifikation", "correct": false, "because": "Kern der Analyse"}, {"text": "Bewertungskriterien", "correct": false, "because": "Strukturieren Prozess"}, {"text": "Präsentationsdesign", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich ein Projekt auf Gefahren prüfe?', 4, '[{"text": "Risiken identifizieren und priorisieren", "correct": true, "because": "Strukturierter Ansatz"}, {"text": "Nur Experten befragen", "correct": false, "because": "Eingeschränkt"}, {"text": "Ohne Plan starten", "correct": false, "because": "Unstrukturiert"}]');
